        {
            if (double.IsNaN(value))
            {
                return "NaN";
            }
            if (double.IsPositiveInfinity(value))
            {
                return "Infinity";
            }
            if (double.IsNegativeInfinity(value))
            {
                return "-Infinity";
            }
            if (value == 0)
            {
                return BitConverter.DoubleToInt64Bits(value) < 0 ? "-0" : "0";
            }
            string digits;
            int e;
            Shortest(value, isFloat, out digits, out e);
            int k = digits.Length;
            int n = e + 1;
            string sign = value < 0 ? "-" : "";
            if (k <= n && n <= 21)
            {
