            }
            if (0 < n && n <= 21)
            {
                return sign + digits.Substring(0, n) + "." + digits.Substring(n);
            }
            if (-6 < n && n <= 0)
            {
                return sign + "0." + new string('0', -n) + digits;
            }
            string text = digits.Substring(0, 1);
            if (k > 1)
            {
                text += "." + digits.Substring(1);
            }
            return sign + text + (e < 0 ? "e-" : "e+") + Math.Abs(e).ToString(CultureInfo.InvariantCulture);
        }

