        /// <summary>The number of a string member's bytes before its trailing NULs.</summary>
        internal static int Used(byte[] data)
        {
            int n = data.Length;
            while (n > 0 && data[n - 1] == 0)
            {
                n--;
            }
            return n;
        }

        // Fills dst with text, each character one byte (U+0000 to U+00FF),
        // zero-padded; invalid if there are more than dst.Length.
        internal static void TextToBytes(List<int> text, byte[] dst)
        {
            if (text.Count > dst.Length)
            {
                throw Invalid("string too long");
            }
            foreach (int c in text)
            {
                if (c > 0xFF)
                {
                    throw Invalid("a character that is not one byte");
                }
            }
            Array.Clear(dst, 0, dst.Length);
            for (int i = 0; i < text.Count; i++)
            {
                dst[i] = (byte)text[i];
            }
        }

        // Decodes UTF-8 between start and end into chars (if not null); false
        // if it is not UTF-8: overlong forms, surrogates and code points
        // above U+10FFFF are not.
        internal static bool DecodeUtf8(byte[] s, int start, int end, List<int> chars)
        {
            int i = start;
            while (i < end)
            {
                int b = s[i];
                if (b < 0x80)
                {
                    if (chars != null)
                    {
                        chars.Add(b);
                    }
                    i++;
                    continue;
                }
                int count, cp, lo = 0x80, hi = 0xBF;
                if (b >= 0xC2 && b <= 0xDF)
                {
                    count = 1;
                    cp = b & 0x1F;
                }
                else if (b >= 0xE0 && b <= 0xEF)
                {
                    count = 2;
                    cp = b & 0x0F;
                    if (b == 0xE0)
                    {
                        lo = 0xA0;
                    }
                    else if (b == 0xED)
                    {
                        hi = 0x9F;
                    }
                }
                else if (b >= 0xF0 && b <= 0xF4)
                {
                    count = 3;
                    cp = b & 0x07;
                    if (b == 0xF0)
                    {
                        lo = 0x90;
                    }
                    else if (b == 0xF4)
                    {
                        hi = 0x8F;
                    }
                }
                else
                {
                    return false;
                }
                if (end - i - 1 < count)
                {
                    return false;
                }
                for (int j = 1; j <= count; j++)
                {
                    int c = s[i + j];
                    if (c < (j == 1 ? lo : 0x80) || c > (j == 1 ? hi : 0xBF))
                    {
                        return false;
                    }
                    cp = cp << 6 | (c & 0x3F);
                }
                if (chars != null)
                {
                    chars.Add(cp);
                }
                i += count + 1;
            }
            return true;
        }

