            return DecodeUtf8(utf8, 0, utf8.Length, chars) ? chars.ToArray() : null;
        }

        /// <summary>A string as characters; null if it holds a lone surrogate.</summary>
        internal static int[] Chars(string text)
        {
            if (text == null)
            {
                throw new ArgumentNullException(nameof(text));
            }
            List<int> chars = new List<int>(text.Length);
            for (int i = 0; i < text.Length; i++)
            {
                char c = text[i];
                if (char.IsHighSurrogate(c) && i + 1 < text.Length && char.IsLowSurrogate(text[i + 1]))
                {
                    chars.Add(char.ConvertToUtf32(c, text[i + 1]));
                    i++;
                }
                else if (char.IsSurrogate(c))
                {
                    return null;
                }
                else
                {
                    chars.Add(c);
                }
            }
            return chars.ToArray();
        }

        // Characters, every one a Unicode scalar value, as a string.
        internal static string Str(IList<int> chars, int start, int count)
        {
            StringBuilder text = new StringBuilder(count);
            for (int i = start; i < start + count; i++)
            {
                if (chars[i] < 0x10000)
                {
                    text.Append((char)chars[i]);
                }
                else
                {
                    text.Append(char.ConvertFromUtf32(chars[i]));
                }
            }
            return text.ToString();
        }

        internal static bool IsSpace(int c)
        {
            return c == ' ' || c == '\t' || c == '\n' || c == '\r';
        }

        internal static bool IsHex(int c)
        {
            return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
        }

        internal static int HexValue(int c)
        {
            return c <= '9' ? c - '0' : (c | 0x20) - 'a' + 10;
        }

        internal static bool HasPrefix(int[] s, int i, string word)
        {
            foreach (char c in word)
            {
                if (i >= s.Length || s[i] != c)
                {
                    return false;
                }
                i++;
            }
            return true;
        }

        internal const string HexDigits = "0123456789abcdef";
    }

    // ------------------------------------------------------------------ JSON

    internal sealed class SwJsonMember
    {
        internal string Name;
        internal SwJson Value;
    }

    /// <summary>
    /// A parsed JSON value. Kind is 'o' (Members), 'a' (Items), 's' (Chars),
    /// 'n' (Number, its text), 'b' (boolean) or 'z' (null).
    /// </summary>
    internal sealed class SwJson
    {
        internal char Kind;
        internal List<SwJsonMember> Members = new List<SwJsonMember>();
        internal List<SwJson> Items = new List<SwJson>();
        internal List<int> Chars = new List<int>();
        internal string Number = "";

        private SwJson(char kind)
        {
            Kind = kind;
        }

        private sealed class Parser
        {
            private readonly int[] s;
            private int i;

            internal Parser(int[] s)
            {
                this.s = s;
            }

            internal bool AtEnd
            {
                get { return i == s.Length; }
            }

            internal void Space()
            {
                while (i < s.Length && SwText.IsSpace(s[i]))
                {
                    i++;
                }
            }

            private void Expect(char c)
            {
                if (i >= s.Length || s[i] != c)
                {
                    throw SwText.Invalid("expected " + c);
                }
                i++;
            }

            private void Literal(string word)
            {
                if (!SwText.HasPrefix(s, i, word))
                {
                    throw SwText.Invalid("expected " + word);
                }
                i += word.Length;
            }

            private int Hex4()
            {
                if (i + 4 > s.Length)
                {
                    throw SwText.Invalid("bad \\u escape");
                }
                int cp = 0;
                for (int j = i; j < i + 4; j++)
                {
                    if (!SwText.IsHex(s[j]))
                    {
                        throw SwText.Invalid("bad \\u escape");
                    }
                    cp = cp * 16 + SwText.HexValue(s[j]);
                }
                i += 4;
                return cp;
            }

            private List<int> Str()
            {
                Expect('"');
                List<int> chars = new List<int>();
                while (i < s.Length)
                {
                    int c = s[i++];
                    if (c == '"')
                    {
                        return chars;
                    }
                    if (c < 0x20)
                    {
                        throw SwText.Invalid("control character in a string");
                    }
                    if (c != '\\')
                    {
                        chars.Add(c);
                        continue;
                    }
                    if (i >= s.Length)
                    {
                        break;
                    }
                    int e = s[i++];
                    switch (e)
                    {
                        case '"':
                        case '\\':
                        case '/':
                            chars.Add(e);
                            break;
                        case 'b':
                            chars.Add('\b');
                            break;
                        case 'f':
                            chars.Add('\f');
                            break;
                        case 'n':
                            chars.Add('\n');
                            break;
                        case 'r':
                            chars.Add('\r');
                            break;
                        case 't':
                            chars.Add('\t');
                            break;
                        case 'u':
                            int cp = Hex4();
                            if (cp >= 0xDC00 && cp <= 0xDFFF)
                            {
                                throw SwText.Invalid("lone low surrogate");
                            }
                            if (cp >= 0xD800 && cp <= 0xDBFF)
                            {
                                Literal("\\u");
                                int low = Hex4();
                                if (low < 0xDC00 || low > 0xDFFF)
                                {
                                    throw SwText.Invalid("lone high surrogate");
                                }
                                cp = 0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00);
                            }
                            chars.Add(cp);
                            break;
                        default:
                            throw SwText.Invalid("bad escape");
                    }
                }
                throw SwText.Invalid("unterminated string");
            }

            private string Number()
            {
                int start = i;
                while (i < s.Length && s[i] < 0x80 && "0123456789+-.eE".IndexOf((char)s[i]) >= 0)
                {
                    i++;
                }
                string text = SwText.Str(s, start, i - start);
                if (!SwText.IsNumber(text))
                {
                    throw SwText.Invalid("bad number");
                }
                return text;
            }

            internal SwJson Value(int depth)
            {
                if (i >= s.Length)
                {
                    throw SwText.Invalid("expected a value");
                }
                int c = s[i];
                switch (c)
                {
                    case '{':
                    case '[':
                        {
                            depth++;
                            if (depth > SwText.MaxDepth)
                            {
                                throw SwText.Invalid("nested too deeply");
                            }
                            SwJson v = new SwJson(c == '{' ? 'o' : 'a');
                            char end = c == '{' ? '}' : ']';
                            i++;
                            Space();
                            if (i < s.Length && s[i] == end)
                            {
                                i++;
                                return v;
                            }
                            while (true)
                            {
                                Space();
                                if (c == '{')
                                {
                                    List<int> name = Str();
                                    Space();
                                    Expect(':');
                                    Space();
                                    SwJson item = Value(depth);
                                    v.Members.Add(new SwJsonMember { Name = SwText.Str(name, 0, name.Count), Value = item });
                                }
                                else
                                {
                                    v.Items.Add(Value(depth));
                                }
                                Space();
                                if (i < s.Length && s[i] == ',')
                                {
                                    i++;
                                    continue;
                                }
                                Expect(end);
                                return v;
                            }
                        }
                    case '"':
                        {
                            SwJson v = new SwJson('s');
                            v.Chars = Str();
                            return v;
                        }
                    case 't':
                        Literal("true");
                        return new SwJson('b');
                    case 'f':
                        Literal("false");
                        return new SwJson('b');
                    case 'n':
                        Literal("null");
                        return new SwJson('z');
                }
                SwJson number = new SwJson('n');
                number.Number = Number();
                return number;
            }
        }

        /// <summary>
        /// Parses a whole JSON document, surrounding whitespace allowed.
        /// Invalid if it is null (not UTF-8), not well-formed JSON or nests
        /// too deeply.
        /// </summary>
        internal static SwJson Parse(int[] chars)
        {
            if (chars == null)
            {
                throw SwText.Invalid("not UTF-8");
            }
            Parser p = new Parser(chars);
            p.Space();
            SwJson v = p.Value(0);
            p.Space();
            if (!p.AtEnd)
            {
                throw SwText.Invalid("text after the value");
            }
            return v;
        }

        /// <summary>The members of an object, in order, repeats and all.</summary>
        internal static List<SwJsonMember> MembersOf(SwJson v)
        {
            if (v.Kind != 'o')
            {
                throw SwText.Invalid("not an object");
            }
            return v.Members;
        }

        // A number member's text: a JSON number, or a string holding one (as
        // 64-bit integers, NaN and the infinities are written).
        private static string Text(SwJson v)
        {
            switch (v.Kind)
            {
                case 'n':
                    return v.Number;
                case 's':
                    return SwText.Str(v.Chars, 0, v.Chars.Count);
            }
            throw SwText.Invalid("not a number");
        }

        /// <summary>
        /// An integer member, which must be whole and in range, of the type
        /// or of a bitfield bits wide.
        /// </summary>
        internal static ulong Int(SwJson v, string type, int bits)
        {
            return SwText.ToInteger(Text(v), type, bits);
        }

        /// <summary>A float or double member.</summary>
        internal static double Real(SwJson v, string type)
        {
            return SwText.ToReal(Text(v), type);
        }

        /// <summary>Reads a string member into dst: each character one byte.</summary>
        internal static void Bytes(SwJson v, byte[] dst)
        {
            if (v.Kind != 's')
            {
                throw SwText.Invalid("not a string");
            }
            SwText.TextToBytes(v.Chars, dst);
        }
    }

    /// <summary>
    /// Writes the canonical JSON form: no whitespace, members in order.
    /// </summary>
    internal sealed class SwJsonWriter
    {
        private readonly StringBuilder text = new StringBuilder();
        private bool first;

        internal void BeginObject()
        {
            text.Append('{');
            first = true;
        }

        internal void EndObject()
        {
            text.Append('}');
            first = false;
        }

        internal void Key(string name)
        {
            if (!first)
            {
                text.Append(',');
            }
            first = false;
            text.Append('"').Append(name).Append("\":");
        }

        internal void Int32(string name, int value)
        {
            Key(name);
            text.Append(SwText.Integer(value));
        }

        internal void UInt32(string name, uint value)
        {
            Key(name);
            text.Append(SwText.Integer(value));
        }

        // 64-bit integers are written as strings.
        internal void Int64(string name, long value)
        {
            Key(name);
            text.Append('"').Append(SwText.Integer(value)).Append('"');
        }

        internal void UInt64(string name, ulong value)
        {
            Key(name);
            text.Append('"').Append(SwText.Integer(value)).Append('"');
        }

        internal void Float(string name, float value)
        {
            Real(name, SwText.RealText(value, true));
        }

        internal void Double(string name, double value)
        {
            Real(name, SwText.RealText(value, false));
        }

        // NaN and the infinities are written as strings.
        private void Real(string name, string value)
        {
            Key(name);
            if (SwText.IsNumber(value))
            {
                text.Append(value);
            }
            else
            {
                text.Append('"').Append(value).Append('"');
            }
        }

        /// <summary>
        /// A string member: its bytes up to the trailing NULs, printable
        /// ASCII as is (but " and \ escaped), every other byte as \u00xx.
        /// </summary>
        internal void Bytes(string name, byte[] data)
        {
            Key(name);
            text.Append('"');
            int used = SwText.Used(data);
            for (int i = 0; i < used; i++)
            {
                byte b = data[i];
                if (b == '"' || b == '\\')
                {
                    text.Append('\\').Append((char)b);
                }
                else if (b >= 0x20 && b <= 0x7E)
                {
                    text.Append((char)b);
                }
                else
                {
                    text.Append("\\u00").Append(SwText.HexDigits[b >> 4]).Append(SwText.HexDigits[b & 15]);
                }
            }
            text.Append('"');
        }

        public override string ToString()
        {
            return text.ToString();
        }
    }

    // ------------------------------------------------------------------- XML

    /// <summary>
    /// A parsed element: its attributes, child elements and character data
    /// (text and CDATA, entities decoded, line ends normalized).
    /// </summary>
    internal sealed class SwXml
    {
        internal string Name;
        internal List<KeyValuePair<string, string>> Attributes = new List<KeyValuePair<string, string>>();
        internal List<int> Text = new List<int>();
        internal List<SwXml> Children = new List<SwXml>();

        private bool Attribute(string name, out string value)
        {
            foreach (KeyValuePair<string, string> a in Attributes)
            {
                if (a.Key == name)
                {
                    value = a.Value;
                    return true;
                }
            }
            value = null;
            return false;
        }

        private static bool NameStart(int c)
        {
            return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || c == ':' || c >= 0x80;
        }

        private static bool NameChar(int c)
        {
            return NameStart(c) || (c >= '0' && c <= '9') || c == '-' || c == '.';
        }

        // Reads a subset of XML 1.0 that is enough for messages: elements,
        // attributes, character data, CDATA, comments, processing
        // instructions, the predefined entities and character references. A
        // document type declaration, and so any other entity, is rejected.
        private sealed class Parser
        {
            internal readonly int[] s;
            internal int i;

            internal Parser(int[] s)
            {
                this.s = s;
            }

            internal bool Starts(string word)
            {
                return SwText.HasPrefix(s, i, word);
            }

            internal void Space()
            {
                while (i < s.Length && SwText.IsSpace(s[i]))
                {
                    i++;
                }
            }

            private int Find(string word, int from)
            {
                for (int at = from; at < s.Length; at++)
                {
                    if (SwText.HasPrefix(s, at, word))
                    {
                        return at;
                    }
                }
                return -1;
            }

            internal void SkipPast(string end)
            {
                int at = Find(end, i);
                if (at < 0)
                {
                    throw SwText.Invalid("unterminated");
                }
                i = at + end.Length;
            }

            internal void Misc()
            {
                while (true)
                {
                    Space();
                    if (Starts("<!--"))
                    {
                        i += 4;
                        SkipPast("-->");
                    }
                    else if (Starts("<?"))
                    {
                        i += 2;
                        SkipPast("?>");
                    }
                    else if (Starts("<!"))
                    {
                        throw SwText.Invalid("a document type declaration");
                    }
                    else
                    {
                        return;
                    }
                }
            }

            private string Name()
            {
                if (i >= s.Length || !NameStart(s[i]))
                {
                    throw SwText.Invalid("expected a name");
                }
                int start = i;
                while (i < s.Length && NameChar(s[i]))
                {
                    i++;
                }
                return SwText.Str(s, start, i - start);
            }

            private void Reference(List<int> chars)
            {
                int semi = Find(";", i);
                if (semi < 0)
                {
                    throw SwText.Invalid("unterminated reference");
                }
                string reference = SwText.Str(s, i, semi - i);
                i = semi + 1;
                switch (reference)
                {
                    case "lt":
                        chars.Add('<');
                        return;
                    case "gt":
                        chars.Add('>');
                        return;
                    case "amp":
                        chars.Add('&');
                        return;
                    case "quot":
                        chars.Add('"');
                        return;
                    case "apos":
                        chars.Add('\'');
                        return;
                }
                if (reference.Length > 1 && reference[0] == '#')
                {
                    bool hexadecimal = reference[1] == 'x';
                    string digits = reference.Substring(hexadecimal ? 2 : 1);
                    if (digits.Length == 0 || digits.Length > 8)
                    {
                        throw SwText.Invalid("bad character reference");
                    }
                    long v = 0;
                    foreach (char c in digits)
                    {
                        if (!(c >= '0' && c <= '9') && !(hexadecimal && SwText.IsHex(c)))
                        {
                            throw SwText.Invalid("bad character reference");
                        }
                        v = v * (hexadecimal ? 16 : 10) + SwText.HexValue(c);
                    }
                    if (!(v == 0x9 || v == 0xA || v == 0xD || (v >= 0x20 && v <= 0xD7FF) ||
                          (v >= 0xE000 && v <= 0xFFFD) || (v >= 0x10000 && v <= 0x10FFFF)))
                    {
                        throw SwText.Invalid("character not allowed");
                    }
                    chars.Add((int)v);
                    return;
                }
                throw SwText.Invalid("unknown entity");
            }

            // Reads character data up to stop (not consumed).
            private void Chars(List<int> chars, int stop, bool attribute)
            {
                while (i < s.Length && s[i] != stop)
                {
                    int c = s[i];
                    if (c == '<')
                    {
                        throw SwText.Invalid("< in an attribute");
                    }
                    if (c == '&')
                    {
                        i++;
                        Reference(chars);
                        continue;
                    }
                    if (c == '\r')
                    {
                        // CR LF and a lone CR are both a line end.
                        i++;
                        if (i < s.Length && s[i] == '\n')
                        {
                            i++;
                        }
                        chars.Add(attribute ? ' ' : '\n');
                        continue;
                    }
                    chars.Add(attribute && (c == '\n' || c == '\t') ? ' ' : c);
                    i++;
                }
            }

            internal SwXml Element(int depth)
            {
                depth++;
                if (depth > SwText.MaxDepth)
                {
                    throw SwText.Invalid("nested too deeply");
                }
                i++; // '<'
                SwXml node = new SwXml { Name = Name() };
                while (true)
                {
                    int before = i;
                    Space();
                    if (i >= s.Length)
                    {
                        throw SwText.Invalid("unterminated start tag");
                    }
                    if (Starts("/>"))
                    {
                        i += 2;
                        return node;
                    }
                    if (s[i] == '>')
                    {
                        i++;
                        break;
                    }
                    if (i == before)
                    {
                        throw SwText.Invalid("attributes must be separated by whitespace");
                    }
                    string name = Name();
                    Space();
                    if (i >= s.Length || s[i] != '=')
                    {
                        throw SwText.Invalid("expected =");
                    }
                    i++;
                    Space();
                    if (i >= s.Length || (s[i] != '"' && s[i] != '\''))
                    {
                        throw SwText.Invalid("expected a quote");
                    }
                    int quote = s[i++];
                    List<int> value = new List<int>();
                    Chars(value, quote, true);
                    if (i >= s.Length)
                    {
                        throw SwText.Invalid("unterminated attribute");
                    }
                    i++;
                    string repeated;
                    if (node.Attribute(name, out repeated))
                    {
                        throw SwText.Invalid("repeated attribute");
                    }
                    node.Attributes.Add(new KeyValuePair<string, string>(name, SwText.Str(value, 0, value.Count)));
                }

                while (true)
                {
                    if (i >= s.Length)
                    {
                        throw SwText.Invalid("unterminated element");
                    }
                    if (Starts("</"))
                    {
                        i += 2;
                        if (Name() != node.Name)
                        {
                            throw SwText.Invalid("mismatched end tag");
                        }
                        Space();
                        if (i >= s.Length || s[i] != '>')
                        {
                            throw SwText.Invalid("bad end tag");
                        }
                        i++;
                        return node;
                    }
                    if (Starts("<!--"))
                    {
                        i += 4;
                        SkipPast("-->");
                    }
                    else if (Starts("<![CDATA["))
                    {
                        i += 9;
                        int end = Find("]]>", i);
                        if (end < 0)
                        {
                            throw SwText.Invalid("unterminated CDATA");
                        }
                        for (int j = i; j < end; j++)
                        {
                            int c = s[j];
                            if (c == '\r')
                            {
                                if (j + 1 < end && s[j + 1] == '\n')
                                {
                                    j++;
                                }
                                c = '\n';
                            }
                            node.Text.Add(c);
                        }
                        i = end + 3;
                    }
                    else if (Starts("<?"))
                    {
                        i += 2;
                        SkipPast("?>");
                    }
                    else if (Starts("<!"))
                    {
                        throw SwText.Invalid("a declaration in content");
                    }
                    else if (s[i] == '<')
                    {
                        node.Children.Add(Element(depth));
                    }
                    else
                    {
                        Chars(node.Text, '<', false);
                    }
                }
            }
        }

        /// <summary>
        /// Parses a whole XML document whose root element is root. Invalid if
        /// it is null (not UTF-8) or not well-formed in the subset the parser
        /// takes.
        /// </summary>
        internal static SwXml Parse(int[] s, string root)
        {
            if (s == null)
            {
                throw SwText.Invalid("not UTF-8");
            }
            foreach (int c in s)
            {
                if ((c < 0x20 && c != 0x9 && c != 0xA && c != 0xD) || c == 0xFFFE || c == 0xFFFF)
                {
                    throw SwText.Invalid("character not allowed in XML");
                }
            }
            Parser p = new Parser(s);
            if (p.Starts("<?xml") && s.Length > 5 && SwText.IsSpace(s[5]))
            {
                p.SkipPast("?>");
            }
            p.Misc();
            if (p.i >= s.Length || s[p.i] != '<')
            {
                throw SwText.Invalid("no root element");
            }
            SwXml node = p.Element(0);
            p.Misc();
            if (p.i != s.Length)
            {
                throw SwText.Invalid("text after the root element");
            }
            if (node.Name != root)
            {
                throw SwText.Invalid("root element is not " + root);
            }
            return node;
        }

        private static string Trim(List<int> text)
        {
            return SwText.Str(text, 0, text.Count).Trim(' ', '\t', '\n', '\r');
        }

        /// <summary>
        /// The member elements of an element holding a message, which must
        /// have only whitespace between them.
        /// </summary>
        internal static List<SwXml> MembersOf(SwXml n)
        {
            if (Trim(n.Text).Length != 0)
            {
                throw SwText.Invalid("text in a message element");
            }
            return n.Children;
        }

        // A number member's text: an element holding only its text,
        // surrounding whitespace allowed.
        private static string NumberText(SwXml n)
        {
            if (n.Children.Count > 0)
            {
                throw SwText.Invalid("an element in a number");
            }
            return Trim(n.Text);
        }

        /// <summary>An integer member, as in JSON.</summary>
        internal static ulong Int(SwXml n, string type, int bits)
        {
            return SwText.ToInteger(NumberText(n), type, bits);
        }

        /// <summary>A float or double member, as in JSON.</summary>
        internal static double Real(SwXml n, string type)
        {
            return SwText.ToReal(NumberText(n), type);
        }

        /// <summary>
        /// Reads a string member into dst: the element's text, each character
        /// one byte, or with encoding="hex" the bytes in hexadecimal.
        /// </summary>
        internal static void Bytes(SwXml n, byte[] dst)
        {
            if (n.Children.Count > 0)
            {
                throw SwText.Invalid("an element in a string");
            }
            string encoding;
            if (!n.Attribute("encoding", out encoding))
            {
                SwText.TextToBytes(n.Text, dst);
                return;
            }
            if (encoding != "hex")
            {
                throw SwText.Invalid("unknown encoding");
            }
            string digits = Trim(n.Text);
            if (digits.Length % 2 != 0 || digits.Length / 2 > dst.Length)
            {
                throw SwText.Invalid("bad hex");
            }
            foreach (char c in digits)
            {
                if (!SwText.IsHex(c))
                {
                    throw SwText.Invalid("bad hex");
                }
            }
            Array.Clear(dst, 0, dst.Length);
            for (int i = 0; i < digits.Length; i += 2)
            {
                dst[i / 2] = (byte)(SwText.HexValue(digits[i]) << 4 | SwText.HexValue(digits[i + 1]));
            }
        }
    }

    /// <summary>
    /// Writes the canonical XML form: no declaration, no whitespace between
    /// elements, one element per member.
    /// </summary>
    internal sealed class SwXmlWriter
    {
        private readonly StringBuilder text = new StringBuilder();

        internal void Open(string name)
        {
            text.Append('<').Append(name).Append('>');
        }

        internal void Close(string name)
        {
            text.Append("</").Append(name).Append('>');
        }

        private void Element(string name, string value)
        {
            Open(name);
            text.Append(value);
            Close(name);
        }

        internal void Int32(string name, int value)
        {
            Element(name, SwText.Integer(value));
        }

        internal void UInt32(string name, uint value)
        {
            Element(name, SwText.Integer(value));
        }

        internal void Int64(string name, long value)
        {
            Element(name, SwText.Integer(value));
        }

        internal void UInt64(string name, ulong value)
        {
            Element(name, SwText.Integer(value));
        }

        internal void Float(string name, float value)
        {
            Element(name, SwText.RealText(value, true));
        }

        internal void Double(string name, double value)
        {
            Element(name, SwText.RealText(value, false));
        }

        /// <summary>
        /// A string member: its bytes up to the trailing NULs, escaped, or,
        /// if any byte is not printable ASCII, in hexadecimal with
        /// encoding="hex".
        /// </summary>
        internal void Bytes(string name, byte[] data)
        {
            int used = SwText.Used(data);
            for (int i = 0; i < used; i++)
            {
                if (data[i] < 0x20 || data[i] > 0x7E)
                {
                    text.Append('<').Append(name).Append(" encoding=\"hex\">");
                    for (int j = 0; j < used; j++)
                    {
                        text.Append(SwText.HexDigits[data[j] >> 4]).Append(SwText.HexDigits[data[j] & 15]);
                    }
                    Close(name);
                    return;
                }
            }
            Open(name);
            for (int i = 0; i < used; i++)
            {
                switch ((char)data[i])
                {
                    case '<':
                        text.Append("&lt;");
                        break;
                    case '>':
                        text.Append("&gt;");
                        break;
                    case '&':
                        text.Append("&amp;");
                        break;
                    case '"':
                        text.Append("&quot;");
                        break;
                    case '\'':
                        text.Append("&apos;");
                        break;
                    default:
                        text.Append((char)data[i]);
                        break;
                }
            }
            Close(name);
        }

        public override string ToString()
        {
            return text.ToString();
        }
    }

    // ------------------------------------------------------------------ BSON

    /// <summary>
    /// One BSON element. Which fields hold its value depends on its type:
    /// Data for a string (without its NUL) or binary (with Subtype); Integer
    /// for int32 and int64; Number for double; Low and High for Decimal128;
    /// Document for an embedded document or array.
    /// </summary>
    internal sealed class SwBsonElement
    {
        internal string Name;
        internal byte Type;
        internal byte[] Data;
        internal byte Subtype;
        internal long Integer;
        internal double Number;
        internal ulong Low;
        internal ulong High;
        internal SwBsonElement[] Document;
    }

    internal static class SwBson
    {
        internal const byte Double = 0x01;
        internal const byte String = 0x02;
        internal const byte EmbeddedDocument = 0x03;
        internal const byte Array = 0x04;
        internal const byte Binary = 0x05;
        internal const byte Undefined = 0x06;
        internal const byte ObjectId = 0x07;
        internal const byte Bool = 0x08;
        internal const byte Datetime = 0x09;
        internal const byte Null = 0x0A;
        internal const byte Regex = 0x0B;
        internal const byte DbPointer = 0x0C;
        internal const byte JavaScript = 0x0D;
        internal const byte Symbol = 0x0E;
        internal const byte CodeWithScope = 0x0F;
        internal const byte Int32 = 0x10;
        internal const byte Timestamp = 0x11;
        internal const byte Int64 = 0x12;
        internal const byte Decimal128 = 0x13;
        internal const byte MinKey = 0xFF;
        internal const byte MaxKey = 0x7F;

        // The high word of a Decimal128 holding an integer: exponent 0 (6176
        // biased), positive.
        internal const ulong Decimal128IntegerHigh = 6176UL << 49;
        // The quiet NaN every NaN is written as.
        internal const ulong CanonicalNaN = 0x7FF8000000000000UL;

        internal static int GetInt32(byte[] s, int at)
        {
            return s[at] | s[at + 1] << 8 | s[at + 2] << 16 | s[at + 3] << 24;
        }

        internal static ulong GetUInt64(byte[] s, int at)
        {
            return unchecked((uint)GetInt32(s, at) | (ulong)(uint)GetInt32(s, at + 4) << 32);
        }

        // Reads a document or an element's value between at and end, checking
        // every length against the bytes there are.
        private sealed class Parser
        {
            private readonly byte[] s;

            internal Parser(byte[] s)
            {
                this.s = s;
            }

            internal SwBsonElement[] Document(int pos, int end, int depth, out int next)
            {
                if (depth > SwText.MaxDepth || end - pos < 5)
                {
                    throw SwText.Invalid("bad document");
                }
                int length = GetInt32(s, pos);
                if (length < 5 || length > end - pos)
                {
                    throw SwText.Invalid("bad document length");
                }
                int last = pos + length - 1;
                if (s[last] != 0)
                {
                    throw SwText.Invalid("no document terminator");
                }
                List<SwBsonElement> elements = new List<SwBsonElement>();
                int at = pos + 4;
                while (at < last)
                {
                    elements.Add(Element(at, last, depth, out at));
                }
                next = last + 1;
                return elements.ToArray();
            }

            private string CString(int at, int end, out int next)
            {
                int nul = System.Array.IndexOf(s, (byte)0, at, end - at);
                if (nul < 0)
                {
                    throw SwText.Invalid("unterminated cstring");
                }
                if (!SwText.DecodeUtf8(s, at, nul, null))
                {
                    throw SwText.Invalid("not UTF-8");
                }
                next = nul + 1;
                return Encoding.UTF8.GetString(s, at, nul - at);
            }

            private byte[] Str(int at, int end, out int next)
            {
                if (end - at < 4)
                {
                    throw SwText.Invalid("bad string");
                }
                int length = GetInt32(s, at);
                if (length < 1 || length > end - at - 4)
                {
                    throw SwText.Invalid("bad string length");
                }
                int nul = at + 4 + length - 1;
                if (s[nul] != 0)
                {
                    throw SwText.Invalid("unterminated string");
                }
                if (!SwText.DecodeUtf8(s, at + 4, nul, null))
                {
                    throw SwText.Invalid("not UTF-8");
                }
                next = nul + 1;
                return Slice(at + 4, length - 1);
            }

            private byte[] Slice(int at, int length)
            {
                byte[] data = new byte[length];
                System.Array.Copy(s, at, data, 0, length);
                return data;
            }

            private static int Fixed(int at, int end, int width)
            {
                if (end - at < width)
                {
                    throw SwText.Invalid("cut short");
                }
                return at + width;
            }

            private SwBsonElement Element(int at, int end, int depth, out int next)
            {
                SwBsonElement e = new SwBsonElement { Type = s[at] };
                e.Name = CString(at + 1, end, out at);
                int start = at;
                switch (e.Type)
                {
                    case Double:
                        at = Fixed(at, end, 8);
                        e.Number = BitConverter.Int64BitsToDouble(unchecked((long)GetUInt64(s, start)));
                        break;
                    case String:
                    case JavaScript:
                    case Symbol:
                        e.Data = Str(at, end, out at);
                        break;
                    case EmbeddedDocument:
                    case Array:
                        e.Document = Document(at, end, depth + 1, out at);
                        break;
                    case Binary:
                        {
                            if (end - at < 5)
                            {
                                throw SwText.Invalid("bad binary");
                            }
                            int length = GetInt32(s, at);
                            if (length < 0 || length > end - at - 5)
                            {
                                throw SwText.Invalid("bad binary length");
                            }
                            e.Subtype = s[at + 4];
                            e.Data = Slice(at + 5, length);
                            at += 5 + length;
                            break;
                        }
                    case Undefined:
                    case Null:
                    case MinKey:
                    case MaxKey:
                        break;
                    case ObjectId:
                        at = Fixed(at, end, 12);
                        break;
                    case Bool:
                        at = Fixed(at, end, 1);
                        if (s[start] > 1)
                        {
                            throw SwText.Invalid("bad bool");
                        }
                        break;
                    case Datetime:
                    case Timestamp:
                        at = Fixed(at, end, 8);
                        break;
                    case Int32:
                        at = Fixed(at, end, 4);
                        e.Integer = GetInt32(s, start);
                        break;
                    case Int64:
                        at = Fixed(at, end, 8);
                        e.Integer = unchecked((long)GetUInt64(s, start));
                        break;
                    case Decimal128:
                        at = Fixed(at, end, 16);
                        e.Low = GetUInt64(s, start);
                        e.High = GetUInt64(s, start + 8);
                        break;
                    case Regex:
                        CString(at, end, out at);
                        CString(at, end, out at);
                        break;
                    case DbPointer:
                        Str(at, end, out at);
                        at = Fixed(at, end, 12);
                        break;
                    case CodeWithScope:
                        {
                            // int32 total length, then a string and a document
                            // filling it.
                            if (end - at < 4)
                            {
                                throw SwText.Invalid("bad code with scope");
                            }
                            int length = GetInt32(s, at);
                            if (length < 4 || length > end - at)
                            {
                                throw SwText.Invalid("bad code with scope length");
                            }
                            int stop = at + length;
                            Str(at + 4, stop, out at);
                            Document(at, stop, depth + 1, out at);
                            if (at != stop)
                            {
                                throw SwText.Invalid("bad code with scope length");
                            }
                            break;
                        }
                    default:
                        // An unknown type: its length is unknown, so nothing
                        // after it can be read.
                        throw SwText.Invalid("unknown element type");
                }
                next = at;
                return e;
            }
        }

        /// <summary>
        /// Parses a whole BSON document: its length must be exactly the
        /// input's. Its elements, in order, repeats and all.
        /// </summary>
        internal static SwBsonElement[] Parse(byte[] input)
        {
            if (input == null)
            {
                throw new ArgumentNullException(nameof(input));
            }
            int end;
            SwBsonElement[] elements = new Parser(input).Document(0, input.Length, 1, out end);
            if (end != input.Length)
            {
                throw SwText.Invalid("bytes after the document");
            }
            return elements;
        }

        // A Decimal128 (BID) as a whole number of at most 64 bits, as its
        // sign and magnitude; false if it is infinite, NaN, not canonical,
        // not whole, or larger.
        private static bool DecimalInteger(ulong low, ulong high, out bool negative, out ulong magnitude)
        {
            negative = false;
            magnitude = 0;
            if (((high >> 61) & 3) == 3)
            {
                return false;
            }
            int exponent = (int)((high >> 49) & 0x3FFF) - 6176;
            BigInteger coefficient = new BigInteger(high & 0x1FFFFFFFFFFFFUL) << 64 | new BigInteger(low);
            if (coefficient >= BigInteger.Pow(10, 34))
            {
                return false;
            }
            if (coefficient.IsZero)
            {
                return true;
            }
            if (exponent < 0)
            {
                BigInteger remainder;
                coefficient = BigInteger.DivRem(coefficient, BigInteger.Pow(10, -exponent), out remainder);
                if (!remainder.IsZero)
                {
                    return false;
                }
            }
            else if (exponent > 0)
            {
                if (exponent > 20)
                {
                    return false;
                }
                coefficient *= BigInteger.Pow(10, exponent);
            }
            if (coefficient > ulong.MaxValue)
            {
                return false;
            }
            negative = (high >> 63) != 0;
            magnitude = (ulong)coefficient;
            return true;
        }

        /// <summary>
        /// An integer member from an int32, int64, Decimal128 or double that
        /// is a whole number in its range.
        /// </summary>
        internal static ulong Int(SwBsonElement e, string type, int bits)
        {
            switch (e.Type)
            {
                case Int32:
                case Int64:
                    return SwText.FitInteger(e.Integer, type, bits);
                case Decimal128:
                    {
                        bool negative;
                        ulong magnitude;
                        if (!DecimalInteger(e.Low, e.High, out negative, out magnitude))
                        {
                            throw SwText.Invalid("not a whole number of at most 64 bits");
                        }
                        return SwText.FitDecimal(negative, magnitude, type, bits);
                    }
                case Double:
                    {
                        double d = e.Number;
                        if (double.IsNaN(d) || double.IsInfinity(d) || d != Math.Truncate(d) || Math.Abs(d) >= 18446744073709551616.0)
                        {
                            throw SwText.Invalid("not a whole number");
                        }
                        return SwText.FitDecimal(d < 0, (ulong)Math.Abs(d), type, bits);
                    }
            }
            throw SwText.Invalid("not a number");
        }

        /// <summary>
        /// A float or double member from a double (rounded to the type, too
        /// large for it invalid), int32 or int64.
        /// </summary>
        internal static double Real(SwBsonElement e, string type)
        {
            switch (e.Type)
            {
                case Int32:
                case Int64:
                    return SwText.RoundInteger(e.Integer, type == "float");
                case Double:
                    break;
                default:
                    throw SwText.Invalid("not a number");
            }
            double d = e.Number;
            if (type == "double" || double.IsNaN(d))
            {
                return d;
            }
            // Halfway from the largest float to 2^128 and beyond round to
            // infinity: too large. 0x1.ffffffp+127:
            if (!double.IsInfinity(d) && Math.Abs(d) >= BitConverter.Int64BitsToDouble(0x47EFFFFFF0000000L))
            {
                throw SwText.Invalid("too large for a float");
            }
            return (float)d;
        }

        /// <summary>
        /// Reads a string member into dst from a string or binary (subtype 0)
        /// of at most dst.Length bytes, zero-filled.
        /// </summary>
        internal static void Bytes(SwBsonElement e, byte[] dst)
        {
            if (e.Type != String && (e.Type != Binary || e.Subtype != 0))
            {
                throw SwText.Invalid("not a string");
            }
            if (e.Data.Length > dst.Length)
            {
                throw SwText.Invalid("string too long");
            }
            System.Array.Clear(dst, 0, dst.Length);
            System.Array.Copy(e.Data, dst, e.Data.Length);
        }

        /// <summary>A nested message member's elements.</summary>
        internal static SwBsonElement[] Subdocument(SwBsonElement e)
        {
            if (e.Type != EmbeddedDocument)
            {
                throw SwText.Invalid("not a document");
            }
            return e.Document;
        }
    }

    /// <summary>
    /// Builds a BSON document: each, the outermost included, is
    /// BeginDocument() ... EndDocument(); an embedded one is named first with
    /// Document(name).
    /// </summary>
    internal sealed class SwBsonWriter
    {
        private byte[] buffer = new byte[64];
        private int length;
        private readonly Stack<int> starts = new Stack<int>();

        private void Append(byte b)
        {
            if (length == buffer.Length)
            {
                System.Array.Resize(ref buffer, buffer.Length * 2);
            }
            buffer[length++] = b;
        }

        private void Append(byte[] bytes, int count)
        {
            for (int i = 0; i < count; i++)
            {
                Append(bytes[i]);
            }
        }

        private void AppendUInt32(uint value)
        {
            for (int i = 0; i < 4; i++)
            {
                Append(unchecked((byte)(value >> (8 * i))));
            }
        }

        private void AppendUInt64(ulong value)
        {
            for (int i = 0; i < 8; i++)
            {
                Append(unchecked((byte)(value >> (8 * i))));
            }
        }

        internal void BeginDocument()
        {
            starts.Push(length);
            AppendUInt32(0);
        }

        internal void EndDocument()
        {
            Append(0);
            int start = starts.Pop();
            uint size = (uint)(length - start);
            for (int i = 0; i < 4; i++)
            {
                buffer[start + i] = unchecked((byte)(size >> (8 * i)));
            }
        }

        private void Head(byte type, string name)
        {
            Append(type);
            byte[] bytes = Encoding.UTF8.GetBytes(name);
            Append(bytes, bytes.Length);
            Append(0);
        }

        internal void Document(string name)
        {
            Head(SwBson.EmbeddedDocument, name);
        }

        // Types up to 32 bits but uint32_t are int32 (a char as signed).
        internal void Int32(string name, int value)
        {
            Head(SwBson.Int32, name);
            AppendUInt32(unchecked((uint)value));
        }

        internal void UInt32(string name, uint value)
        {
            Int64(name, value);
        }

        internal void Int64(string name, long value)
        {
            Head(SwBson.Int64, name);
            AppendUInt64(unchecked((ulong)value));
        }

        // A uint64_t above 2^63-1 is a Decimal128, so no tool sees it
        // negative.
        internal void UInt64(string name, ulong value)
        {
            if (value <= long.MaxValue)
            {
                Int64(name, (long)value);
                return;
            }
            Head(SwBson.Decimal128, name);
            AppendUInt64(value);
            AppendUInt64(SwBson.Decimal128IntegerHigh);
        }

        internal void Float(string name, float value)
        {
            Double(name, value);
        }

        internal void Double(string name, double value)
        {
            Head(SwBson.Double, name);
            AppendUInt64(double.IsNaN(value) ? SwBson.CanonicalNaN : unchecked((ulong)BitConverter.DoubleToInt64Bits(value)));
        }

        /// <summary>
        /// A string member: its bytes up to the trailing NULs, as a string if
        /// they are UTF-8 holding no NUL, otherwise as binary (subtype 0).
        /// </summary>
        internal void Bytes(string name, byte[] data)
        {
            int used = SwText.Used(data);
            if (System.Array.IndexOf(data, (byte)0, 0, used) < 0 && SwText.DecodeUtf8(data, 0, used, null))
            {
                Head(SwBson.String, name);
                AppendUInt32((uint)(used + 1));
                Append(data, used);
                Append(0);
                return;
            }
            Head(SwBson.Binary, name);
            AppendUInt32((uint)used);
            Append(0);
            Append(data, used);
        }

        internal byte[] ToArray()
        {
            byte[] bytes = new byte[length];
            System.Array.Copy(buffer, bytes, length);
            return bytes;
        }
    }
}
